def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None or v <= 0 or not math.isfinite(v):
        return 0.0
    props = s.get('element_properties', {})
    total = 0.0
    weight = 0.0
    for e, f in s.get('composition', {}).items():
        r = props.get(e, {}).get('covalent_radius_A')
        if f > 0 and r is not None and r > 0 and math.isfinite(r):
            total += f * r * r * r
            weight += f
    return float(4.0 * math.pi * total / (3.0 * weight * v)) if weight > 0 else 0.0

def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None or v <= 0 or not math.isfinite(v):
        return 0.0
    props = s.get('element_properties', {})
    total = 0.0
    weight = 0.0
    for e, f in s.get('composition', {}).items():
        z = props.get(e, {}).get('valence_electrons')
        if f > 0 and z is not None and z >= 0 and math.isfinite(z):
            total += f * z
            weight += f
    return float(total / (weight * v)) if weight > 0 else 0.0

def feature(s):
    props = s.get('element_properties', {})
    values = {}
    inverse = 0.0
    numerator = 0.0
    for e, f in s.get('composition', {}).items():
        p = props.get(e, {})
        ie = p.get('first_ionization_energy_eV')
        ea = p.get('electron_affinity_eV')
        if f > 0 and ie is not None and ea is not None and math.isfinite(ie) and math.isfinite(ea) and ie - ea > 1e-6:
            chi = 0.5 * (ie + ea)
            hardness = 0.5 * (ie - ea)
            values[e] = (chi, hardness)
            inverse += f / hardness
            numerator += f * chi / hardness
    if inverse <= 0:
        return 0.0
    mu = numerator / inverse
    charges = {e: (mu - v[0]) / v[1] for e, v in values.items()}
    sites = s.get('sites', ())
    occ = [max(0.0, float(t.get('occupancy', 1.0) or 0.0)) for t in sites]
    q = [charges.get(t.get('element', ''), 0.0) for t in sites]
    weight = sum(occ)
    if weight <= 0:
        return 0.0
    total = 0.0
    for b in s.get('neighbors', ()):
        i = b['i']
        j = b['j']
        d = b.get('distance_A')
        if d is not None and d > 1e-8 and math.isfinite(d):
            total += occ[i] * occ[j] * q[i] * q[j] * math.exp(-d / 3.0) / d
    return float(0.5 * total / weight)
